def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    path = []

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.' and (row, col) not in visited

    def find_path(row, col):
        if (row, col) == goal:
            path.append((row, col))
            return True

        visited.add((row, col))
        path.append((row, col))

        # Explore neighbors
        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]
        for r, c in neighbors:
            if is_valid(r, c) and find_path(r, c):
                return True

        # Backtrack
        path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    if find_path(start[0], start[1]):
        return path
    else:
        return []

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols or \
       goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols:
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    queue = [(start, [start])]
    visited = {start}

    while queue:
        (row, col), path = queue.pop(0)

        if (row, col) == goal:
            return path

        neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]

        for r, c in neighbors:
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))

    return []

